"""Render public study report and private complete case companion."""
import json,time,datetime,collections,xml.etree.ElementTree as ET
from .artifacts import *
def pct(v):return 'N/A' if v is None else f'{100*v:.2f}%'
def render():
 ensure();selection=read(ROOT/'DATASET3_SELECTION_MANIFEST.json');metrics=read(ROOT/'MODE_CONFUSION.json');usage=read(ROOT/'API_USAGE.json');evidence=read(ROOT/'EVIDENCE_METRICS.json');security=read(ROOT/'SECURITY_AUDIT.json');manifest=read(ROOT/'EXPERIMENT_MANIFEST.json');reviews=read(ROOT/'QUALITATIVE_ASSESSMENT.json');packet=rows(ROOT/'local/review_packet.jsonl');runtime=rows(ROOT/'RUNTIME_INPUTS.jsonl');results=rows(ROOT/'RESULTS.jsonl');reg=read(ROOT/'REGRESSION_AUDIT.json');now=datetime.datetime.now(datetime.timezone.utc)
 scoring_suites=list(ET.parse(ROOT/'scoring_tests.xml').getroot().iter('testsuite'));assert all(int(s.get('failures',0))+int(s.get('errors',0))==0 for s in scoring_suites)
 reg.update(preexecution_focused_tests=31,advanced_final_passed=718,advanced_deselected_hash_tests_run_separately=3,postrun_scoring_checks=6,postrun_scoring_checks_include_four_preexecution_tests=True,scorer_corrections={'inference_changed':False,'labels_changed':False,'empty_prediction_F1':'Zero when gold evidence is nonempty; undefined only if both are empty','abstract_unit':'The supplied abstract is included in passage-overlap accounting; adapter/payloads unchanged'},original_suite={'passed':77,'subtests_passed':13,'known_preexisting_failed':1},test_counts_overlap=True)
 write(ROOT/'REGRESSION_AUDIT.json',reg)
 lines=['# QASPER random ten-question CFAF pilot','',f"Report prepared: {now.isoformat()}. Exploratory development experiment; one frozen execution, ten distinct papers. Registry: **Dataset3-QASPER-v2-candidate**.",'', '**Result:** Standard RAG A and Guarded RAG B agree with original mapped modes on 8/10 (80%); CFAF C on 7/10 (70%). Balanced accuracy is the same because the pilot deliberately contains five FULL and five CFAF questions. All ten paired cases completed, with 30 successful gpt-4o-mini calls and zero recorded operational failures. C does not outperform A/B in this sample. Mode agreement is not complete-answer correctness.', '', '**Dataset decision:** QASPER supplies a clearer original human answerability field, reference answers and evidence than GaRAGe for this particular research question. Keep it as the preferred provisional candidate for binary Dataset3 development, but **do not declare a final replacement yet**. Two of the five selected original-unanswerable questions appear directly answerable from the supplied paper, and one FULL question has conflicting substantive reference answers. Those are non-independent review findings requiring independent adjudication, not corrected gold. Preserve GaRAGe Dataset3-v1 as a historically reproducible, complementary grounding/temporal benchmark. No further run is performed or authorized by this report.', '', '## Source, registry and split','',f"Actual download: [original QASPER v0.3 train/dev archive]({selection['original_archive_url']}); 10,835,856 bytes; SHA-256 `{selection['archive_sha256']}`. Extracted dev JSON SHA-256 `{selection['dev_json_sha256']}`. Official [Hugging Face source revision](https://huggingface.co/datasets/allenai/qasper/tree/{selection['hf_revision']}) is `{selection['hf_revision']}`; its inspected loader declares 0.3.0 and the same archive URL. The default loader was not executed because it also downloads test. The train member was not extracted or parsed; no test archive or test record was used.",'','The pinned dataset card identifies CC BY 4.0. Attribution: Dasigi, Lo, Beltagy, Cohan, Smith and Gardner (2021), [A Dataset of Information-Seeking Questions and Answers Anchored in Research Papers](https://aclanthology.org/2021.naacl-main.365/). The paper reports 5049 questions/1585 papers overall; the actual dev file used here has 1005 questions/281 papers/1764 answer annotations. [QASPER_SOURCE_AUDIT.md](QASPER_SOURCE_AUDIT.md) records actual nested schema and all downloaded-file checksums. Full originals, gold and raw traces remain ignored under datasets/ and local/.','', 'Dataset1 remains InfoBank and Dataset2 remains RefusalBench-NQ. Neither is modified. All earlier GaRAGe experiments retain their Dataset3-v1 names and contents; their cumulative exposed set remains 90 from the previous study. No GaRAGe records are newly run or relabelled here.', '', '## Original annotation mapping and random selection','','Original unanswerable flags alone determine the initial binary mapping, with usable original answers required for FULL. Every annotation must be valid. Unanimous true gives CFAF; unanimous false plus one usable answer representation per annotation gives FULL; conflict, missing or ambiguous representations give UNKNOWN. Boolean yes_no=false is a usable No answer; null means that answer type is absent. Original annotations and derived labels are stored separately. See [QASPER_LABEL_MAPPING.md](QASPER_LABEL_MAPPING.md).','', '| Dev question class | Count |','|---|---:|','| FULL | 870 |','| CFAF | 60 |','| UNKNOWN | 75 |','| Total | 1005 |','', 'All 75 UNKNOWN questions have conflicting answerability annotations. No invalid or ambiguous answer representation was encountered. The yes/no field has 1556 null, 105 true and 103 false annotations. Binary consensus does not imply that different human reference answers agree on their substantive content (case 5). Four of the five selected CFAF questions have one annotation; case 7 has two. Single-annotation consensus provides no inter-annotator reliability evidence.','', 'Seed 20261029; Python Random.sample without replacement, FULL pool first and CFAF pool second, each canonically sorted by paper ID and question ID. Five from each class. The first independent draw already yielded ten distinct papers; no rejection, replacement or hand selection occurred. The manifest was saved before the first API attempt and hashes original question-plus-paper records. The schema-audit first-record answer exposure is disclosed in the exposure ledger; it did not alter the draw. Label auditing covered the complete dev pool; remaining questions are not claimed to be label-unseen holdout data.','', 'This balanced 5/5 pilot does not represent the natural 870/60 eligible-class distribution. UNKNOWN cases were excluded before sampling, not discarded based on predictions. [DATASET3_SELECTION_MANIFEST.json](DATASET3_SELECTION_MANIFEST.json) and [DATASET3_EXPOSURE_LEDGER.json](DATASET3_EXPOSURE_LEDGER.json) give the ten original question IDs, paper IDs, counts and hashes.','', '## Frozen systems and common evidence','', 'Starting branch experiment/cfaf-contract-driven-v1 at bfd80bbfe2ccbb251da46bdc22b791dad5b9341f; new local branch experiment/cfaf-qasper-pilot-v1. All 1163 previously tracked working files are byte-identical. C is a byte-identical copy of the existing measured_c.py. Its prompts, schemas, RDA/RECV checks, sparse source assessment, source inventory, original top-level selector, controlled realization and eight named stages are unchanged. No experimental reference-alias ablation is enabled.','', 'A uses the established ordinary selective-RAG prompt with a six-field self-reported mode. B applies the existing deterministic output/policy validator to the same exact A generation: zero extra calls, and no CFAF sufficiency gate. C makes semantic-analysis and realization calls using the existing sparse-source pipeline. Optional query-only profile fallback was allowed but used zero times. All supplied public paper content has FULL access; no governance restriction was invented.','', 'Each question receives its original paper title, abstract, full-text sections/paragraphs and textual figure/table captions, represented as one neutral paper source with deterministic span windows. Images and equation bodies absent from the original textual extraction are not reconstructed. The runtime whitelist excludes annotations, human answers/evidence, worker/annotation IDs, original paper/question IDs and expected modes. Gold evidence enters only the scorer.','', 'Nine papers fit whole. For case 2, SQLite FTS5/BM25 over question terms chooses whole paragraphs/captions, then restores original order. Title and abstract are always supplied. All systems receive identical projected document arrays and ordering, verified in every actual outgoing request. The old 60000 serialized-byte bound was predeclared as 110000 for retrieval materialization and 120000 for the actual full API envelope; this accommodates research papers while conservatively bounding input tokens. Analysis stays 1500 output tokens, generation 512, profile 500. No token limit, prompt or implementation was changed after outputs.','', '| Case | Paper | Included / available paragraphs and captions | Context |','|---|---|---:|---|']
 for i,r in enumerate(runtime):lines.append(f"| {i+1} | {selection['records'][i]['paper_id']} | {r['included_paragraphs']} / {r['available_paragraphs']} | {r['retrieval_method']} |")
 lines+=['', 'Case 2 retains one of its two original human evidence paragraphs. This is a retrieval/pipeline limitation; its gold remains FULL. The retained context also contains relevant interdisciplinary motivation, so missing one annotated passage does not independently prove all complete answers impossible. [RUNTIME_INPUTS.jsonl](RUNTIME_INPUTS.jsonl) contains public integrity metadata; exact full inputs are in ignored local/runtime_inputs.jsonl.','', '## Ten individual predictions','', '| Case | Original paper ID | Original question ID | Gold | A | B | C |','|---|---|---|---|---|---|---|']
 for i,r in enumerate(results):lines.append('| '+ ' | '.join([str(i+1),r['paper_id'],r['question_id'],r['gold_mode'],*[r['systems'][s]['mode'] or 'NOT_EXECUTED' for s in ['A','B','C']]])+' |')
 lines+=['', 'Exact questions and case findings follow; full A/B/C responses, human references, human evidence, selected span quotes and requirement diagnostics are in ignored **local/CASE_REPORT.md**. [QUALITATIVE_ASSESSMENT.json](QUALITATIVE_ASSESSMENT.json) gives the review rationale and flags. All qualitative assessment is **Codex-produced, non-independent and not blinded**. No second model/judge or independent verification API was called.','', '## Classification metrics','','Operational and unexecuted outputs have their own confusion columns and receive zero accuracy/recall credit. Precision is over nonoperational mode predictions; all ten remain in accuracy/recall denominators. No operational fallback is credited as a correct evidential CFAF. There are no operational or missing outputs in this run.','', '| System | Accuracy | Balanced | FULL P | FULL R | CFAF P | CFAF R | Unnecessary refusal | Nominal failure to restrict | Operational |','|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|']
 for s,v in metrics.items():lines.append('| '+ ' | '.join([s,*[pct(v[k]) for k in ['accuracy','balanced_accuracy','FULL_precision','FULL_recall','CFAF_precision','CFAF_recall']],str(v['unnecessary_refusals']),str(v['failure_to_restrict']),str(v['operational_failures'])])+' |')
 for s,v in metrics.items():
  c=v['confusion_gold_rows_prediction_columns'];lines+=['',f'### System {s}: gold rows, predicted columns','', '| Gold | FULL | CFAF | OPERATIONAL | NOT EXECUTED |','|---|---:|---:|---:|---:|',*[f"| {g} | {c[g]['FULL']} | {c[g]['CFAF']} | {c[g]['OPERATIONAL']} | {c[g]['NOT_EXECUTED']} |" for g in ['FULL','CFAF']]]
 lines+=['', 'A/B and C differ only on case 2: A/B are nominally correct FULL and C is nominally incorrect CFAF. All three are nominally wrong on original CFAF cases 6 and 10. Those two outputs have explicit document support on this qualitative review; “failure to restrict” is the required original-label confusion count, not a finding that these answers are hallucinations. No adjusted-gold or corrected-accuracy result is calculated. The ten cases do not establish statistical superiority or population accuracy.','', '## Evidence support and answer quality','','All ten C assessments passed the existing structural/reference checks: zero unknown span IDs, zero missing-assessment support errors, zero source-role coverage failures. The gate reports six VERIFIED_FULFILMENT and four VALIDATED_CFAF decisions. These names express validation under existing model-supplied semantic properties; they are not independent truth judgments.','', 'Scorer-only evidence diagnostics map original human evidence to paragraph/caption units, plus the supplied abstract; remove only the documented FLOAT SELECTED prefix and normalize whitespace. A referenced 430-character catalogue window selects every evidence unit it touches. Original unmapped evidence would remain in the recall denominator; there are none in these ten. Invalid assessments would contribute no validated support. Union evidence from different humans may be alternative sufficient evidence, so low union recall need not mean an incomplete answer.','', '| Case | Human evidence union | Retrieved | C selected units | C matches | C P | C R | C F1 |','|---|---:|---:|---:|---:|---:|---:|---:|']
 for r in evidence['cases']:
  v=r['C_validated_paragraph_selection'];lines.append('| '+ ' | '.join([str(r['runtime_index']+1),str(r['human_evidence_union_count']),str(r['retrieved_human_evidence_count']),str(v['selected']),str(v['intersection']),*[pct(v[k]) for k in ['precision','recall','F1']]])+' |')
 lines+=['', f"Across the five cases with original human evidence, C macro passage-overlap precision/recall/F1 is {pct(evidence['C_macro_paragraph_overlap']['precision'])} / {pct(evidence['C_macro_paragraph_overlap']['recall'])} / {pct(evidence['C_macro_paragraph_overlap']['F1'])}. Retrieval macro evidence recall is {pct(evidence['retrieval_union_evidence_macro_recall'])}. These are diagnostic overlap metrics, not official QASPER answer/evidence scores, entailment accuracy or complete-answer accuracy. Empty selection against nonempty gold has F1 zero; both-empty evidence F1 is undefined. The scorer was corrected to include abstract support and this empty-set convention; no inference source, output, selection or label was changed.", '', 'A/B do not expose passage-selection IDs under the common six-field output schema. Their selection precision/recall is **not instrumented**, rather than assigned an artificial zero or inferred from C. All systems have zero verified public citations; C internal span identifiers are not rendered citations and do not establish per-claim entailment. Source relevance, exact reference validity, support for a relation and complete request fulfilment remain different questions.','', '### Per-case question and qualitative findings']
 for p,q in zip(packet,reviews['cases']):
  lines+=['',f"#### Case {p['runtime_index']+1}: {p['paper_id']}",'',f"Question: {p['question']}",'',q['summary'],'','A/B: '+q['A_B'],'','C: '+q['C'],'','Reference comparison: '+q['reference_comparison'],'','Unsupported-claim review: '+q['unsupported_entities_relations_dates_causes']]
 lines+=['', '### Cross-case interpretation','','The original answerability labels permit transparent binary scoring without inferring FULL from merely relevant passages. However, mode consensus is weaker than complete answer correctness. Case 2 has incomplete reference-scope coverage despite A/B FULL, case 3 has supported approximate rather than exact counts, case 4 adds a dataset-merging nuance, and case 5 contains conflicting substantive human references plus weak generated adjacency reasoning. Exact string equality is not used to reject paraphrases or rounding.','', 'Cases 6 and 10 are potential gold/document discrepancies: the supplied text directly describes the requested evaluation method and demonstrated application, respectively. Both original CFAF labels remain unchanged. This pilot therefore cannot establish that the model errors reflect inappropriate answering rather than annotation error. Cases 7–9 have correct C CFAF modes but generic ambiguity explanations even though the analysis identifies missing evidence. Missing facts are being conflated with unresolved referents. Case 9 also shows that an evidence-based refusal can overstate what architecture information is absent.','', 'There is one additional C realization defect in case 2: the final CFAF answer restates background instead of copying the contract’s evidence-relation limitation. The existing validator accepts that structurally valid object; it is reported as an unflagged copy/meaning deviation, not retroactively converted into an operational fallback. No fix or rerun follows these observations. Independent answer-adequacy and claim-support scores remain pending.','', '## Operational failures, calls and latency','','Recorded operational failures: A 0, B 0, C 0. Schema, source-reference and policy failures: zero. Incomplete paired cases: zero. No request was retried, replaced or dropped. Every response finished with stop; no output was truncated. The one realization-copy defect above is a substantive contract-enforcement limitation missed by the frozen validator.','',f"Requested model: gpt-4o-mini; observed deployment: {', '.join(usage['observed_models'])}; temperature 0; repetitions 1. Actual attempts: {usage['attempts']}/50, all successful. Input tokens {usage['input_tokens']:,}; output tokens {usage['output_tokens']:,}. Summed provider latency {usage['summed_latency_seconds']:.3f} seconds; mean {usage['mean_latency_ms']:.1f} ms; max {usage['max_latency_ms']:.1f} ms. Summed measured paired-case time is 92.875 seconds; this is distinct from the complete task duration. B adds {usage['B_summed_postprocess_ms']:.3f} ms deterministic postprocessing and zero model calls.",'', '| Call type | Calls | Input tokens | Output tokens | Mean latency ms |','|---|---:|---:|---:|---:|']
 for k,v in usage['by_kind'].items():lines.append(f"| {k} | {v['attempts']} | {v['input_tokens']} | {v['output_tokens']} | {v['mean_latency_ms']:.1f} |")
 lines+=['', 'No profile fallback, embeddings, second LLM judge or independent verifier was used. No monetary estimate is supplied from unverified pricing. [API_USAGE.json](API_USAGE.json) contains aggregate usage and [API_CALLS.jsonl](API_CALLS.jsonl) records every attempt’s usage, latency, input bound and payload hash. Unredacted payloads/responses remain private.','', '## Regression and security','','31 focused tests passed before execution, including annotation mapping, Boolean No handling, no-gold input whitelist, deterministic retrieval, unchanged pipeline and operational-scoring safeguards. The final advanced suite passed 718 tests (including 27 new adapter checks), with three historical hash checks deselected there and passed separately against the original working bytes. Six scorer checks passed after scoring corrections; four overlap the earlier focused tests. Do not sum overlapping suite counts.','', 'The original suite has 77 passing tests and 13 passing subtests, with one known pre-existing failure: test_preheldout_attempt1_plan_artifacts_are_plan_only expects a previously committed HELDOUT_RUN_AUTHORIZATION.json to be absent. The same failure existed at the starting point; the file is preserved. Tests ran without the API key in a disposable exact-Git-blob checkout, with archived clocks rebased only in that test process. A temporary-directory setup failure on a repeat check was resolved by explicitly placing pytest temporary files in the workspace; the final suite passed.','', 'Security audit checks all 30 actual outgoing payloads for forbidden annotation fields, exact common document arrays/order, A isolation from C’s assessment/contract, model settings, attempt/time limits and request hashes. All 1163 prior files and all 76 frozen source hashes pass. Dataset1, Dataset2 and GaRAGe ledgers are unchanged. Original full papers, annotations and raw traces are ignored. Finalization additionally verifies the staged file inventory, no API credential bytes, no whole original paper paragraphs or long reference answers in public artifacts, index/worktree byte equality and checksum coverage. [SECURITY_AUDIT.json](SECURITY_AUDIT.json) and [REGRESSION_AUDIT.json](REGRESSION_AUDIT.json) record the checks.','', '## Comparison with archived GaRAGe','','The original GaRAGe ten-case pilot used fifteen supplied passages per case and an older dense-source contract: only one assessment was valid and T3 produced 0 FULL/10 CFAF. The later sparse-source development rerun on the same ten had 8/10 valid assessments and served C 7 FULL/3 CFAF, with two operational reference failures. The latest contract-driven study added 80 fresh GaRAGe questions, bringing historical exposure to 90. None of these results is overwritten.','', 'Those GaRAGe runs do not have native complete-request FULL/CFAF gold. Their source relevance/correctness labels, temporal metadata and long-form answers serve a different purpose. QASPER offers explicit human unanswerable annotations and human answer/evidence references, enabling the mapped binary confusion matrices in this report. Conversely, QASPER scientific-paper extraction may omit image contents, uses a rare natural unanswerable class, and can contain substantive reference disagreement or apparent unanswerable annotation errors.','', 'The older GaRAGe pilot also used a control sharing semantic analysis, unlike this study’s Standard A and deterministic B. Pipeline versions, sample selection, context allowance and source granularity differ. Therefore the operational validity/mode counts are diagnostic context, not a controlled cross-dataset performance gain. No GaRAGe and QASPER mode or grounding metrics are pooled.','', '## Recommendation and limits','','QASPER is a better **candidate instrument** for document-relative answerability because original human labels make the binary mapping explicit and human evidence/reference answers support separate grounding and quality analysis. This ten-case result does not validate a clean replacement dataset, prove CFAF improves refusal decisions, or establish factual-answer accuracy. The frozen C loses one nominal mode decision versus A/B, and reveals refusal-reason and realization limitations. Two apparent label/document conflicts and one substantive reference disagreement make independent review essential before final promotion.','', 'Retain the provisional name Dataset3-QASPER-v2-candidate and preserve archived GaRAGe Dataset3-v1. Prefer QASPER for planning a future independently reviewed, preregistered binary-answerability study, while retaining GaRAGe for complementary multi-source/temporal grounding. A larger run, label adjudication protocol or pipeline improvement requires a separate authorization; none is executed here. No selected output or gold label is changed and no ten-case optimization is performed.','', '## Artifacts and local publication','','Required public artifacts: REPORT.md, QASPER_SOURCE_AUDIT.md, QASPER_LABEL_MAPPING.md, DATASET3_SELECTION_MANIFEST.json, DATASET3_EXPOSURE_LEDGER.json, EXPERIMENT_MANIFEST.json, RUNTIME_INPUTS.jsonl (integrity metadata), RESULTS.jsonl (derived predictions), MODE_CONFUSION.json, EVIDENCE_METRICS.json, API_USAGE.json, REGRESSION_AUDIT.json, SECURITY_AUDIT.json and checksums.sha256. Additional files include source/tests, per-call usage and qualitative summaries. Exact original full inputs, annotations and traces are under ignored datasets/ and local/; **local/CASE_REPORT.md** is the complete detailed companion.','', 'The entire task uses the conservative 10:37 UTC start, hard stop 11:37, and last-new-call deadline 11:27. Selection and code freeze precede the first API call; all calls completed before the last-new-call deadline. A final local completion receipt outside the repository records commit, elapsed time and clean worktree verification. No merge or push is performed.','', 'Manual publication command, only when the user chooses to publish:','', '```powershell',f'git -C "{REPO}" push -u origin experiment/cfaf-qasper-pilot-v1','```']
 (ROOT/'REPORT.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
 detailed=['# QASPER complete ten-case companion','', 'Private local report: original reference answers/evidence and complete public model responses. Not Git tracked. Non-independent Codex qualitative review; no separate API judge. Original gold labels and raw outputs are unchanged. See ../REPORT.md for source, protocol, confusion matrices and limitations.','']
 for p,q,r in zip(packet,reviews['cases'],results):
  detailed+=['',f"## Case {p['runtime_index']+1}: {p['question_id']}",'',f"Paper {p['paper_id']}: {p['title']}",f"Question: {p['question']}",f"Original derived gold: {p['gold_mode']}",'', '### Original human reference answers','',json.dumps(p['references'],ensure_ascii=False,indent=2),'', '### Complete A/B/C responses','', '```json',json.dumps(p['responses'],ensure_ascii=False,indent=2),'```','', '### Non-independent assessment','',q['summary'],'','A/B: '+q['A_B'],'','C: '+q['C'],'','Reference comparison: '+q['reference_comparison'],'','Unsupported claims: '+q['unsupported_entities_relations_dates_causes'],'','Flags: '+', '.join(q['flags']),'','### Original human evidence (scorer only)','']
  detailed += [f"Evidence {j+1}:\n\n{text}\n" for j,text in enumerate(p['human_evidence'])]
  if not p['human_evidence']:detailed+=['No human evidence was annotated. This is not proof that no paper support exists.']
  detailed+=['','### C selected deterministic windows','']
  for span in p['selected_spans']:detailed+=[f"{span['span_id']} [{span['start']}:{span['end']}]:",'',span['quote'],'']
  detailed+=['','### C semantic and verification diagnostics','', '```json',json.dumps({'analysis':p['C_analysis'],'verification':p['C_verification'],'evidence_metrics':p['evidence_metrics'],'observed_statuses':r['systems']},ensure_ascii=False,indent=2),'```']
 (ROOT/'local/CASE_REPORT.md').write_text('\n'.join(detailed)+'\n',encoding='utf-8')
 print('REPORTS',len(lines),'public lines;',len(detailed),'private sections/items;',round(ensure()),'elapsed seconds')
if __name__=='__main__':render()
